import copy
import math


def _is_num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _check_nonempty_str(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("expected non-empty string")
    return value


def _check_unique_classes(value):
    if not isinstance(value, list):
        raise ValueError("classes must be a list")
    out = []
    for item in value:
        _check_nonempty_str(item)
        out.append(item)
    if len(set(out)) != len(out):
        raise ValueError("duplicate class labels")
    return out


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _common_preamble(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    name = contract.get("name")
    if not isinstance(name, str) or not name.strip():
        raise ValueError("contract name must be a non-empty string")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or not all(isinstance(x, str) for x in inputs):
        raise ValueError("contract inputs must be a list of strings")
    if len(payloads) != len(inputs):
        raise ValueError("payload count must match contract inputs")
    return name


def transform(payloads, contract):
    name = _common_preamble(payloads, contract)
    data = _unwrap(payloads[0])
    if not isinstance(data, dict):
        raise ValueError("fit input must be an object")

    for key in ("classes", "sample_weight", "members"):
        if key not in data:
            raise ValueError("missing required field: %s" % key)

    classes = _check_unique_classes(data["classes"])
    class_set = set(classes)

    sample_weight = data["sample_weight"]
    if not isinstance(sample_weight, list):
        raise ValueError("sample_weight must be a list")
    for weight in sample_weight:
        if not _is_num(weight) or weight < 0:
            raise ValueError("sample_weight entries must be non-negative finite numbers")
    sample_count = len(sample_weight)

    members = data["members"]
    if not isinstance(members, list):
        raise ValueError("members must be a list")

    seen_ids = set()
    active = []
    weight_sum = 0.0
    for member in members:
        if not isinstance(member, dict):
            raise ValueError("member must be an object")
        if "id" not in member or "active" not in member:
            raise ValueError("member requires id and active")
        member_id = _check_nonempty_str(member["id"])
        if member_id in seen_ids:
            raise ValueError("duplicate member id: %s" % member_id)
        seen_ids.add(member_id)
        if not isinstance(member["active"], bool):
            raise ValueError("member active must be a boolean")
        if not member["active"]:
            continue

        for key in ("weight", "predictions", "classes", "probabilities"):
            if key not in member:
                raise ValueError("active member requires %s" % key)

        weight = member["weight"]
        if not _is_num(weight) or weight < 0:
            raise ValueError("member weight must be a non-negative finite number")

        predictions = member["predictions"]
        if not isinstance(predictions, list) or len(predictions) != sample_count:
            raise ValueError("member predictions length must equal sample count")
        for label in predictions:
            if not isinstance(label, str) or label not in class_set:
                raise ValueError("member prediction must be a known class")

        member_classes = _check_unique_classes(member["classes"])
        if len(member_classes) != len(classes) or set(member_classes) != class_set:
            raise ValueError("member classes must be a permutation of global classes")

        probabilities = member["probabilities"]
        if not isinstance(probabilities, list) or len(probabilities) != sample_count:
            raise ValueError("probabilities must have one row per sample")
        for row in probabilities:
            if not isinstance(row, list) or len(row) != len(member_classes):
                raise ValueError("probability row width must match member classes")
            row_sum = 0.0
            for value in row:
                if not _is_num(value) or value < 0:
                    raise ValueError("probabilities must be non-negative finite numbers")
                row_sum += value
            if abs(row_sum - 1.0) > 1e-9:
                raise ValueError("probability rows must sum to 1")

        active.append(member)
        weight_sum += weight

    if not active:
        raise ValueError("at least one active member is required")
    if not weight_sum > 0:
        raise ValueError("active member weights must sum to a positive value")

    out_members = []
    for member in active:
        clone = copy.deepcopy(member)
        clone["fit_weight"] = copy.deepcopy(sample_weight)
        out_members.append(clone)

    result = {
        "classes": list(classes),
        "sample_count": sample_count,
        "members": out_members,
    }
    return {"name": name, "result": result}

