import sys
from pathlib import Path

if __package__ in (None, ""):
    sys.path.insert(0, str(Path(__file__).resolve().parent))

from model import load_payload
from transform import transform


def _safe_rel(path):
    if not isinstance(path, str) or path == "":
        raise ValueError("path must be a non-empty string")
    if "\\" in path or ":" in path:
        raise ValueError("unsafe path separator")
    if path.startswith("/"):
        raise ValueError("absolute paths are not allowed")
    parts = path.split("/")
    if any(segment in ("", ".", "..") for segment in parts):
        raise ValueError("unsafe path segment")
    return path


def build_component(root, contract_path):
    root = Path(root)
    contract_path = Path(contract_path)
    contract = load_payload(contract_path)
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    for key in ("name", "inputs", "output"):
        if key not in contract:
            raise ValueError("contract missing field: %s" % key)
    name = contract["name"]
    if not isinstance(name, str) or not name.strip():
        raise ValueError("contract name must be a non-empty string")
    inputs = contract["inputs"]
    if not isinstance(inputs, list) or not all(isinstance(x, str) for x in inputs):
        raise ValueError("contract inputs must be a list of strings")
    rel_inputs = [_safe_rel(item) for item in inputs]

    payloads = [load_payload(root / rel) for rel in rel_inputs]
    result = transform(payloads, contract)

    out_rel = _safe_rel(contract["output"])
    out_path = root / out_rel
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )
    return result


def _locate_root(component_dir, rel_inputs):
    for candidate in [component_dir, *component_dir.parents]:
        if all((candidate / rel).is_file() for rel in rel_inputs):
            return candidate
    raise ValueError("cannot locate workspace root for component inputs")


def main():
    component_dir = Path(__file__).resolve().parent
    contract_path = component_dir / "contract.json"
    contract = load_payload(contract_path)
    if not isinstance(contract, dict) or not isinstance(contract.get("inputs"), list):
        raise ValueError("invalid contract")
    rel_inputs = [_safe_rel(item) for item in contract["inputs"]]
    root = _locate_root(component_dir, rel_inputs)
    build_component(root, contract_path)


if __name__ == "__main__":
    main()

